// The one clock for picture, captions and sound. Shots come from the
// storyboard (src/storyboard.json), voice placement from src/script.json and
// measured voice timings from src/vo.ts (generated by scripts/make-voice.py).
// Scenes, captions and scripts/make-audio.ts all import this file, so a sound
// lands on the frame of its picture. Event times beyond the voice (counter
// steps, clicks, glints) live in src/marks.ts.
import board from './storyboard.json' with {type: 'json'};
import script from './script.json' with {type: 'json'};
import {VO, type LineId} from './vo.ts';

export const FPS = 30;
export const WIDTH = 1080;
export const HEIGHT = 1920;
export const BPM = 120;
/** Frames per beat at 120 BPM. Every cut sits on a beat. */
export const BEAT = (60 / BPM) * FPS;
export const DURATION = board.runtimeSeconds;
export const TOTAL_FRAMES = Math.round(DURATION * FPS);

/** Seconds -> frame (visual marks snap to the nearest frame). */
export const f = (sec: number) => Math.round(sec * FPS);
/** Frame -> seconds. */
export const s = (frame: number) => frame / FPS;

export type Shot = {id: string; scene: string; start: number; end: number; from: number; to: number};
export const SHOTS: Shot[] = board.shots.map((x) => ({id: x.id, scene: x.scene, start: x.start, end: x.end, from: f(x.start), to: f(x.end)}));

export type Scene = {name: string; start: number; end: number; from: number; durationInFrames: number; shots: Shot[]};
/** Consecutive shots of the same scene, in order. Each scene is one <Sequence>, so frame 0 inside a scene is `from`. */
export const SCENES: Scene[] = SHOTS.reduce<Scene[]>((acc, shot) => {
  const last = acc[acc.length - 1];
  if (last && last.name === shot.scene) {
    last.end = shot.end;
    last.durationInFrames = f(shot.end) - last.from;
    last.shots.push(shot);
  } else {
    acc.push({name: shot.scene, start: shot.start, end: shot.end, from: f(shot.start), durationInFrames: f(shot.end) - f(shot.start), shots: [shot]});
  }
  return acc;
}, []);

export const scene = (name: string): Scene => {
  const sc = SCENES.find((x) => x.name === name);
  if (!sc) throw new Error(`No scene ${name}`);
  return sc;
};
export const shot = (id: string): Shot => {
  const sh = SHOTS.find((x) => x.id === id);
  if (!sh) throw new Error(`No shot ${id}`);
  return sh;
};

export type Role = 'rita' | 'ai' | 'gus';
export type Timed = {text: string; start: number; end: number};
export type Cue = {
  id: LineId;
  role: Role;
  /** Heard through Rita's phone (phone-band filter). */
  phone: boolean;
  /** Absolute seconds the clip starts / stops sounding (a hard cut can stop it early). */
  at: number;
  end: number;
  /** Caption chunks and words in absolute seconds. */
  chunks: Timed[];
  words: Timed[];
  /** Absolute second the clip is hard-cut, if it is. */
  cut: number | null;
};

type ScriptLine = {id: string; role: string; at: number; phone?: boolean; cutAfterWord?: string; cutInto?: number};

export const CUES: Cue[] = (script.lines as ScriptLine[]).map((line) => {
  const v = VO[line.id as LineId];
  const words = v.words.map((w) => ({text: w.word, start: line.at + w.start, end: line.at + w.end}));
  let cut: number | null = null;
  if (line.cutAfterWord) {
    const w = words.find((x) => x.text === line.cutAfterWord);
    if (!w) throw new Error(`${line.id}: no word ${line.cutAfterWord}`);
    cut = w.start + (line.cutInto ?? 0);
  }
  const end = cut ?? line.at + v.duration;
  const clip = (t: Timed) => ({...t, start: Math.min(t.start, end), end: Math.min(t.end, end)});
  return {
    id: line.id as LineId,
    role: line.role as Role,
    phone: Boolean(line.phone),
    at: line.at,
    end,
    chunks: v.chunks.map((c) => clip({text: c.text, start: line.at + c.start, end: line.at + c.end})),
    words: words.map(clip),
    cut,
  };
});

export const cue = (id: LineId): Cue => {
  const c = CUES.find((x) => x.id === id);
  if (!c) throw new Error(`No cue ${id}`);
  return c;
};

/** Absolute start second of a word in a line (first match, or the nth with `nth`). */
export const wordAt = (id: LineId, word: string, nth = 0): number => {
  const matches = cue(id).words.filter((w) => w.text.replace(/[^\p{L}\p{N}’'$-]/gu, '') === word.replace(/[^\p{L}\p{N}’'$-]/gu, ''));
  if (!matches[nth]) throw new Error(`${id}: no word ${word}`);
  return matches[nth].start;
};

/** Frame helpers relative to a scene's own Sequence (its frame 0). */
export const local = (sceneName: string, sec: number) => f(sec) - scene(sceneName).from;
